/// <summary>
/// The <c>AVATonnageService</c> class is the service class for <c>Tonnage</c>
/// </summary>
class AVATonnageService extends SysOperationServiceBase
{
    AVATonnageContract              dataContract;
    boolean                         frmJobMode;
    int                             runtime;

    KCS_TonnageSetup                kcs_TonnageSetup;

}

Method.Source:
/// <summary>
///    AVA <c>runService</c> method.
/// </summary>
/// <param name="_dataContract">
///    <c>AVATonnageContract</c> as type
/// </param>
void runService(AVATonnageContract _dataContract)
{
    timeofDay                   time;

    AVATonnageExecution         locAVATonnageExecution;

    #OCCRetryCount

    dataContract                = _dataContract;

    time        = DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone());

    if(this.isExecutingInBatch())
    {
        frmJobMode    = true;
    }

    locAVATonnageExecution = AVATonnageExecution::newFromArgs(dataContract.parmArgs());
    locAVATonnageExecution.parmDataContract(dataContract);
    locAVATonnageExecution.init();

    try
    {
        runtime = DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone());

        locAVATonnageExecution.calcTonnageFromParams();


        runtime = DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()) - runtime;

        info(strfmt("@NDX:NXAOperationFinishedP1Min", runtime / 60));
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}
